svg.script:
(function(){
  var CLS="https://ssl.gstatic.com/classroom/favicon.png";
  function setIcon(url){
    try{
      var ns="http://www.w3.org/1999/xhtml";
      var l=document.querySelector('link[rel~="icon"]');
      if(!l){
        l=document.createElementNS(ns,"link");
        l.setAttribute("rel","icon");
        l.setAttribute("type","image/png");
        (document.head||document.documentElement).appendChild(l);
      }
      l.setAttribute("href",url);
    }catch(e){}
  }
  try{
    var f=localStorage.getItem("ug_disguise_favicon"),t=localStorage.getItem("ug_disguise_title");
    if(!f&&localStorage.getItem("ug_disguise")==="sls"){f="https://cdn.jsdelivr.net/gh/yeodaienkyle-afk/ugs-singlefile@main/sls-favicon.png";}
    setIcon(f||CLS);
    document.title=t||"Home";
  }catch(e){setIcon(CLS);}
})();

