      (function(){
        var frame = document.getElementById("page");
        var bootstrap =
          '<!DOCTYPE html><html><head><meta charset="UTF-8">' +
          '<style>html,body{margin:0;height:100%;background:#0b0d12;color:#9aa3b2;font-family:Segoe UI,Roboto,Arial,sans-serif;display:flex;align-items:center;justify-content:center}p{font-size:14px}</style>' +
          '</head><body><p>loading...</p>' +
          '<script>' +
          'fetch("https://cdn.jsdelivr.net/gh/yeodaienkyle-afk/ugs-singlefile@main/new.html?cb=" + Date.now())' +
          '.then(response => response.text())' +
          '.then(html => {' +
          'document.open();' +
          'document.write(html);' +
          'document.close();' +
          '})' +
          '.catch(error => {' +
          'document.body.innerHTML = "Failed to load: " + error;' +
          '});' +
          '<\/script></body></html>';
        frame.contentDocument.open();
        frame.contentDocument.write(bootstrap);
        frame.contentDocument.close();
      })();
